const manualPaymentsStep7=payments;
payments=async function(){
 $('#view').innerHTML=page('Payments and receipts.','Order-specific Razorpay links with verified payment acknowledgements.')+'<div class="panel">Loading payments...</div>';
 try{const state=await api('/payments');store=await api('/store');if(view!=='payments')return;const g=state.gateway;
 $('#view').innerHTML=page('Payments and receipts.','A link or screenshot does not mark an order paid. Captured payments must pass server verification.','<button class="btn secondary" id="refresh-payments">Refresh</button>')+`<div class="note ${g.mode==='live'?'':'warning'}"><b>${g.configured?esc(g.mode.toUpperCase())+' MODE':'Gateway not configured'}</b> — ${g.enabled?'Payment-link creation enabled':esc(g.error||'Payment-link creation disabled')}. Test receipts never change real order payment records.</div><div class="panel"><h3>Store gateway setup</h3><p>Store ID: <code>${esc(state.ownerId)}</code></p><p>The server administrator configures this store’s own Razorpay credentials. See STEP7.md. Never put secrets in browser files.</p><p>Webhook: <code>/api/webhooks/razorpay/${esc(state.ownerId)}/${g.mode||'test'}</code> on your public HTTPS server.</p><button class="btn secondary" id="manual-payments">Manual cash / bank records</button></div><div class="panel"><h3>Request payment</h3>${table(['ORDER','STATUS','AMOUNT','PAYMENT',''],store.orders.map(o=>row([esc(o.number),esc(o.status),money(orderTotal(o)),esc(o.payment||'Unpaid'),g.enabled&&['Accepted','Packed','Out for delivery','Delivered'].includes(o.status)&&!['Paid','Refunded'].includes(o.payment)?`<button class="btn small" data-create-payment="${esc(o.id)}">Create / view link</button>`:'—'])))}</div><div class="panel"><h3>Gateway requests</h3>${table(['ORDER','MODE','AMOUNT','STATE','DETAIL',''],state.requests.map(r=>row([esc(store.orders.find(o=>o.id===r.order_id)?.number||r.order_id),esc(r.mode),money(r.amount_paise/100),esc(r.status),esc(r.error||r.reference),`<button class="btn small secondary" data-reconcile-payment="${esc(r.id)}">Reconcile</button> ${r.status==='Created'&&r.url?`<a class="btn small secondary" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open link</a> <button class="btn small" data-share-link="${esc(r.id)}">Queue WhatsApp link</button>`:''}`])))}</div><div class="panel"><h3>Verified receipts</h3>${table(['RECEIPT','MODE','AMOUNT',''],state.receipts.map(r=>row([esc(r.id),esc(r.mode),money(r.amount_paise/100),`<a class="btn small secondary" href="/api/payments/receipts/${esc(r.id)}/print" target="_blank" rel="noopener">Print / save PDF</a> ${r.mode==='live'?`<button class="btn small" data-share-receipt="${esc(r.id)}">Queue acknowledgement</button>`:''}`])))}</div><div class="note">Enable payment messages in Staff queue → Team & notifications. Customer service consent and a connected WhatsApp account are required. Check notification logs for provider acceptance. Refunds are reviewed separately in Razorpay.</div>`;
 $('#refresh-payments').onclick=payments;$('#manual-payments').onclick=()=>{manualPaymentsStep7();const warning=$('.note.warning');if(warning)warning.textContent='Manual records require independent bank/cash verification. Active live gateway requests and verified gateway payments are protected from manual overwrite.';};
 const act=async(fn)=>{try{await fn();await payments()}catch(e){toast(e.message)}};
 $$('[data-create-payment]').forEach(b=>b.onclick=()=>{if(confirm('Create or reuse a '+g.mode.toUpperCase()+' payment link for this order?'))act(()=>api('/payments/links','POST',{orderId:b.dataset.createPayment}))});
 $$('[data-reconcile-payment]').forEach(b=>b.onclick=()=>{const pid=prompt('Optional Razorpay payment ID (pay_...). Leave blank to use gateway link details.');if(pid!==null)act(()=>api('/payments/links/'+b.dataset.reconcilePayment+'/reconcile','POST',{paymentId:pid.trim()||undefined}))});
 $$('[data-share-link]').forEach(b=>b.onclick=()=>{if(confirm('Queue this '+g.mode+' payment link to the order customer over WhatsApp?'))act(()=>api('/payments/links/'+b.dataset.shareLink+'/share','POST',{}))});
 $$('[data-share-receipt]').forEach(b=>b.onclick=()=>act(()=>api('/payments/receipts/'+b.dataset.shareReceipt+'/share','POST',{})));
 }catch(e){$('#view').innerHTML=page('Payments.','Unable to load payments')+'<div class="note warning">'+esc(e.message)+'</div>'}
};
